const MODULE_CONTENT = {"en":{"balance-sheet":{"faq":[{"q":"Where do I find a company's balance sheet?","a":"In the annual report, and in the half-yearly results: listed companies publish a statement of assets and liabilities with their results for September and March. Both are on the NSE and BSE company pages and on the company's investor relations page."},{"q":"Standalone or consolidated: which should I read?","a":"Read consolidated when the company has subsidiaries, because it shows the whole group's debt and assets. Standalone can hide borrowings held in subsidiaries. Read standalone too when you want to see what the parent company itself owes."},{"q":"Is a company with zero debt always better?","a":"It is safer, but not automatically better. A business earning a high ROCE can sensibly use some debt to grow. What matters is whether profit covers interest comfortably and whether borrowed money earns more than it costs."},{"q":"What does negative 'other equity' or reserves mean?","a":"Accumulated losses are larger than the profits and premiums retained. The company has lost part of the money shareholders put in. Check whether losses are still growing and how the company is funding itself."}],"quiz":[{"q":"A balance sheet always satisfies which equation?","o":["Assets = Liabilities + Equity","Assets = Revenue − Profit","Equity = Revenue + Debt","Profit = Assets − Revenue"],"a":0,"e":"The balance sheet balances: total assets equal liabilities plus equity."},{"q":"Which of these is a current asset?","o":["Factory building","Cash and receivables due within a year","Long-term investment","Goodwill"],"a":1,"e":"Current assets convert to cash within a year, such as cash, receivables and inventory."},{"q":"A current ratio of 1.6 means:","o":["Profit is 1.6 times sales","Current liabilities are 1.6 times current assets","Current assets cover current liabilities 1.6 times","Debt is 1.6 times equity"],"a":2,"e":"Current ratio = current assets ÷ current liabilities = 1.6, so current assets cover current liabilities 1.6 times."},{"q":"Debt-to-equity of 0.4 means:","o":["Equity is 40% of debt","Profit is 40% of debt","Assets are 40% of equity","Debt is 40% of equity"],"a":3,"e":"0.4 means debt equals 40 percent of shareholders' equity."},{"q":"Which item is part of equity?","o":["Share capital and reserves","Trade payables","Provisions","Long-term loan"],"a":0,"e":"Equity is share capital plus reserves and surplus."},{"q":"Goodwill arises when:","o":["Dividends are paid","A company buys another business above the value of its net assets","A company sells its factory","Shares are split"],"a":1,"e":"Goodwill is the premium paid over net assets in an acquisition."},{"q":"Working capital is calculated as:","o":["Revenue minus expenses","Equity minus goodwill","Current assets minus current liabilities","Total assets minus total debt"],"a":2,"e":"Working capital measures the funds available for daily operations."},{"q":"Contingent liabilities are:","o":["Share capital","Cash in hand","Debts already paid","Possible obligations depending on a future event, such as a lawsuit"],"a":3,"e":"They are disclosed in the notes because they may become real liabilities."},{"q":"Why is a company's total assets figure not proof of strength?","o":["Assets can be overvalued or illiquid","Assets are always cash","Assets are always lower than liabilities","Assets are not reported"],"a":0,"e":"Assets may be overstated, hard to sell, or of low quality."},{"q":"Reserves in equity represent:","o":["Taxes owed","Profits retained in the business over time","Money borrowed from banks","Shares sold to the public this year"],"a":1,"e":"Reserves are accumulated profits not paid out as dividends."},{"q":"Rising receivables faster than sales can indicate:","o":["Debt is being repaid","Profit is falling","Customers may be slow to pay","Inventory is being sold quickly"],"a":2,"e":"A gap between receivables and sales can be an early warning sign."},{"q":"Book value per share is:","o":["Price divided by EPS","Dividend divided by price","Revenue divided by employees","Shareholders' equity divided by the number of shares"],"a":3,"e":"It is the accounting value per share."},{"q":"Which trend over five years is most concerning?","o":["Equity flat while debt rises steadily","Equity rising with stable debt","Reserves growing","Current ratio stable above 1.5"],"a":0,"e":"Rising debt without equity growth raises financial risk."},{"q":"Where are details of borrowings and contingent liabilities usually found?","o":["In the lot size table","In the notes to accounts","In the share price chart","In the broker's advertisement"],"a":1,"e":"The notes give the detail behind the main balance sheet figures."},{"q":"A company with negative working capital is:","o":["Not allowed by SEBI","Always in trouble","Normal for some businesses, such as fast-cash retail","Always profitable"],"a":2,"e":"Negative working capital can be normal depending on the business model."},{"q":"Which ratio helps check short-term safety?","o":["Price-earnings ratio","Dividend yield","Promoter holding","Current ratio"],"a":3,"e":"The current ratio compares short-term assets and obligations."},{"q":"Why compare a bank's balance sheet ratios with a manufacturer's using the same rules?","o":["They are not comparable; each industry has different norms","They always match","Banks have no debt","Manufacturers have no assets"],"a":0,"e":"Industry norms differ, so comparisons must be like-for-like."},{"q":"Equity is the amount left for shareholders after:","o":["Selling all assets","Paying all liabilities","Paying dividends only","Paying taxes only"],"a":1,"e":"Equity equals assets minus liabilities."},{"q":"Long-term investments appear on the balance sheet as:","o":["Equity","Revenue","Non-current assets","Current liabilities"],"a":2,"e":"Investments held for longer than a year are non-current assets."},{"q":"A balance sheet is best described as:","o":["A record of the whole year's cash","A list of future orders","A tax return","A snapshot on one date"],"a":3,"e":"It shows position at a point in time, unlike the profit statement which covers a period."},{"q":"Which step is a sound routine when reading a balance sheet?","o":["Check that assets equal liabilities plus equity, then compare ratios over several years","Read only the total assets figure","Ignore the notes","Compare only with the share price"],"a":0,"e":"A systematic routine with trends avoids single-number mistakes."}]}},"hi":{"balance-sheet":{"faq":[{"q":"कंपनी की बैलेंस शीट कहाँ मिलेगी?","a":"सालाना रिपोर्ट में, और छमाही नतीजों में: सूचीबद्ध कंपनियाँ सितंबर और मार्च के नतीजों के साथ संपत्ति और देनदारी का विवरण देती हैं। दोनों NSE और BSE के कंपनी पेज और कंपनी के निवेशक संबंध पेज पर मिलते हैं।"},{"q":"स्टैंडअलोन या कंसॉलिडेटेड: कौन-सी पढ़ें?","a":"अगर कंपनी की सहायक कंपनियाँ हैं तो कंसॉलिडेटेड पढ़ें, क्योंकि वह पूरे समूह का क़र्ज़ और संपत्ति दिखाती है। स्टैंडअलोन सहायक कंपनियों में रखा क़र्ज़ छिपा सकती है। मूल कंपनी पर ख़ुद कितना बकाया है, यह देखने के लिए स्टैंडअलोन भी पढ़ें।"},{"q":"क्या बिना क़र्ज़ वाली कंपनी हमेशा बेहतर है?","a":"वह सुरक्षित है, पर अपने-आप बेहतर नहीं। ऊँचा ROCE कमाने वाला कारोबार बढ़ने के लिए समझदारी से कुछ क़र्ज़ ले सकता है। अहम यह है कि मुनाफ़ा ब्याज को आराम से ढके और उधार का पैसा अपनी लागत से ज़्यादा कमाए।"},{"q":"नेगेटिव 'अन्य इक्विटी' या रिज़र्व का क्या मतलब है?","a":"जमा हुए घाटे रोके गए मुनाफ़े और प्रीमियम से ज़्यादा हो गए हैं। कंपनी ने शेयरधारकों के लगाए पैसे का एक हिस्सा गँवा दिया है। देखें कि घाटे अब भी बढ़ रहे हैं या नहीं और कंपनी ख़ुद को कैसे फ़ंड कर रही है।"}],"quiz":[{"q":"बैलेंस शीट हमेशा किस समीकरण को पूरा करती है?","o":["संपत्ति = देनदारी + इक्विटी","संपत्ति = राजस्व − मुनाफ़ा","इक्विटी = राजस्व + कर्ज़","मुनाफ़ा = संपत्ति − राजस्व"],"a":0,"e":"बैलेंस शीट संतुलित रहती है: कुल संपत्ति देनदारी और इक्विटी के बराबर।"},{"q":"इनमें से कौन चालू संपत्ति है?","o":["फ़ैक्टरी इमारत","एक साल में देय नकद और प्राप्य राशि","दीर्घकालिक निवेश","गुडविल"],"a":1,"e":"चालू संपत्ति एक साल में नकद बनती है, जैसे नकद, प्राप्य राशि और इन्वेंटरी।"},{"q":"1.6 का चालू अनुपात बताता है:","o":["मुनाफ़ा बिक्री का 1.6 गुना","चालू देनदारी चालू संपत्ति का 1.6 गुना","चालू संपत्ति चालू देनदारी को 1.6 गुना कवर करती है","कर्ज़ इक्विटी का 1.6 गुना"],"a":2,"e":"चालू अनुपात = चालू संपत्ति ÷ चालू देनदारी = 1.6।"},{"q":"0.4 का डेट-टू-इक्विटी बताता है:","o":["इक्विटी कर्ज़ का 40% है","मुनाफ़ा कर्ज़ का 40% है","संपत्ति इक्विटी का 40% है","कर्ज़ इक्विटी का 40% है"],"a":3,"e":"0.4 का मतलब कर्ज़ शेयरधारक इक्विटी का 40 प्रतिशत है।"},{"q":"इक्विटी का हिस्सा कौन सा है?","o":["शेयर पूँजी और रिज़र्व","व्यापार देय राशि","प्रावधान","दीर्घकालिक कर्ज़"],"a":0,"e":"इक्विटी शेयर पूँजी प्लस रिज़र्व और सरप्लस है।"},{"q":"गुडविल तब बनती है जब:","o":["डिविडेंड दिए जाते हैं","कंपनी किसी और कारोबार को उसकी शुद्ध संपत्ति से ज़्यादा में ख़रीदती है","कंपनी अपनी फ़ैक्टरी बेचती है","शेयर स्प्लिट होते हैं"],"a":1,"e":"गुडविल अधिग्रहण में शुद्ध संपत्ति से ऊपर दिया गया प्रीमियम है।"},{"q":"वर्किंग कैपिटल का हिसाब होता है:","o":["राजस्व − खर्च","इक्विटी − गुडविल","चालू संपत्ति − चालू देनदारी","कुल संपत्ति − कुल कर्ज़"],"a":2,"e":"वर्किंग कैपिटल रोज़ के कारोबार के लिए उपलब्ध पैसा मापता है।"},{"q":"आकस्मिक देनदारियाँ हैं:","o":["शेयर पूँजी","हाथ में नकद","चुकाए जा चुके कर्ज़","भविष्य की घटना पर निर्भर संभावित ज़िम्मेदारियाँ, जैसे मुकदमा"],"a":3,"e":"ये नोट्स में दर्ज होती हैं क्योंकि ये असली देनदारी बन सकती हैं।"},{"q":"कुल संपत्ति का आँकड़ा ताकत का सबूत क्यों नहीं?","o":["संपत्ति ज़्यादा आँकी या कम लिक्विड हो सकती है","संपत्ति हमेशा नकद होती है","संपत्ति हमेशा देनदारी से कम होती है","संपत्ति रिपोर्ट नहीं होती"],"a":0,"e":"संपत्ति बढ़ा-चढ़ाकर दिखाई गई, बेचने में कठिन, या कम गुणवत्ता की हो सकती है।"},{"q":"इक्विटी में रिज़र्व दर्शाता है:","o":["देय टैक्स","समय के साथ कारोबार में रखे गए मुनाफ़े","बैंकों से उधार लिया पैसा","इस साल जनता को बेचे शेयर"],"a":1,"e":"रिज़र्व जमा हुए मुनाफ़े हैं जो डिविडेंड में नहीं बाँटे गए।"},{"q":"प्राप्य राशि बिक्री से तेज़ बढ़ें तो संकेत हो सकता है:","o":["कर्ज़ चुकाया जा रहा है","मुनाफ़ा गिर रहा है","ग्राहक देर से भुगतान कर रहे हैं","इन्वेंटरी तेज़ी से बिक रही है"],"a":2,"e":"प्राप्य राशि और बिक्री के बीच अंतर शुरुआती चेतावनी हो सकता है।"},{"q":"बुक वैल्यू प्रति शेयर है:","o":["कीमत ÷ EPS","डिविडेंड ÷ कीमत","राजस्व ÷ कर्मचारी","शेयरधारक इक्विटी ÷ शेयरों की संख्या"],"a":3,"e":"यह प्रति शेयर लेखांकन मूल्य है।"},{"q":"पाँच साल में कौन सा रुझान सबसे चिंताजनक है?","o":["इक्विटी स्थिर और कर्ज़ लगातार बढ़ता हुआ","इक्विटी बढ़ती और कर्ज़ स्थिर","रिज़र्व बढ़ते हुए","चालू अनुपात 1.5 से ऊपर स्थिर"],"a":0,"e":"इक्विटी बढ़े बिना कर्ज़ बढ़ने से वित्तीय जोखिम बढ़ता है।"},{"q":"कर्ज़ और आकस्मिक देनदारी का विवरण आमतौर पर कहाँ मिलता है?","o":["लॉट साइज़ तालिका में","लेखा नोट्स में","शेयर कीमत के चार्ट में","ब्रोकर के विज्ञापन में"],"a":1,"e":"नोट्स मुख्य आँकड़ों के पीछे का विवरण देते हैं।"},{"q":"नकारात्मक वर्किंग कैपिटल वाली कंपनी:","o":["SEBI द्वारा अवैध","हमेशा मुसीबत में","कुछ कारोबारों में सामान्य, जैसे तेज़ नकद वाला खुदरा","हमेशा लाभदायक"],"a":2,"e":"कारोबार मॉडल के अनुसार नकारात्मक वर्किंग कैपिटल सामान्य हो सकता है।"},{"q":"अल्पकालिक सुरक्षा जाँचने के लिए कौन सा अनुपात मदद करता है?","o":["P/E अनुपात","डिविडेंड यील्ड","प्रमोटर होल्डिंग","चालू अनुपात"],"a":3,"e":"चालू अनुपात अल्पकालिक संपत्ति और देनदारी की तुलना करता है।"},{"q":"बैंक और निर्माता के बैलेंस शीट अनुपातों की एक ही नियमों से तुलना क्यों सावधानी से करें?","o":["वे तुलनीय नहीं; हर उद्योग के अलग मानक होते हैं","वे हमेशा मेल खाते हैं","बैंकों में कर्ज़ नहीं होता","निर्माताओं में संपत्ति नहीं होती"],"a":0,"e":"उद्योग मानक अलग होते हैं, इसलिए तुलना समान आधार पर होनी चाहिए।"},{"q":"इक्विटी वह राशि है जो शेयरधारकों के लिए बचती है, इसके बाद:","o":["सारी संपत्ति बेचने के","सारी देनदारी चुकाने के","केवल डिविडेंड देने के","केवल टैक्स चुकाने के"],"a":1,"e":"इक्विटी = संपत्ति − देनदारी।"},{"q":"बैलेंस शीट में दीर्घकालिक निवेश दिखते हैं:","o":["इक्विटी के रूप में","राजस्व के रूप में","गैर-चालू संपत्ति के रूप में","चालू देनदारी के रूप में"],"a":2,"e":"एक साल से अधिक रखे निवेश गैर-चालू संपत्ति होते हैं।"},{"q":"बैलेंस शीट को सबसे अच्छा कैसे वर्णित करें?","o":["पूरे साल के नकद का रिकॉर्ड","भविष्य के ऑर्डरों की सूची","टैक्स रिटर्न","एक तारीख़ पर स्नैपशॉट"],"a":3,"e":"यह किसी समय की स्थिति दिखाती है, जबकि मुनाफ़ा विवरण एक अवधि कवर करता है।"},{"q":"बैलेंस शीट पढ़ते समय सही क्रम कौन सा है?","o":["संपत्ति = देनदारी + इक्विटी जाँचें, फिर कई सालों में अनुपात तुलना करें","केवल कुल संपत्ति का आँकड़ा पढ़ें","नोट्स को अनदेखा करें","केवल शेयर कीमत से तुलना करें"],"a":0,"e":"रुझानों के साथ व्यवस्थित क्रम एक-आँकड़े की गलती से बचाता है।"}]}}};
